<template><main class="mx-auto max-w-5xl px-4 py-10"><div class="flex items-center justify-between"><div><span class="tag bg-emerald-50 text-emerald-700">面试已完成</span><h1 class="mt-3 text-3xl font-bold">面试复盘报告</h1><p class="mt-2 text-slate-500">{{data?.job_title}} · {{data?.company||'目标岗位'}}</p></div><NuxtLink to="/interview/history" class="btn-secondary">返回历史</NuxtLink></div><div v-if="data" class="mt-6 space-y-5"><div class="card grid gap-5 p-6 md:grid-cols-3"><div><p class="text-sm text-slate-500">岗位匹配总分</p><p class="mt-2 text-5xl font-bold text-blue-600">{{data.final_review?.overall_score||0}}</p></div><div class="md:col-span-2"><p class="leading-7 text-slate-700">{{data.final_review?.summary}}</p><p class="mt-3 text-sm text-slate-500">能力覆盖率：{{data.final_review?.coverage||0}}%</p></div></div><div class="card p-6"><h2 class="font-semibold">能力维度</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"> <div v-for="(v,k) in data.final_review?.capability_scores" :key="k"><div class="flex justify-between text-sm"><span>{{k}}</span><b>{{v}}</b></div><div class="mt-1 h-2 rounded bg-slate-100"><div class="h-2 rounded bg-blue-600" :style="{width:`${v}%`}"></div></div></div></div></div><div class="grid gap-5 md:grid-cols-2"><div class="card p-6"><h2 class="font-semibold">薄弱项</h2><ul class="mt-3 list-disc space-y-2 pl-5 text-sm text-slate-600"><li v-for="x in data.final_review?.weak_points" :key="x">{{x}}</li></ul></div><div class="card p-6"><h2 class="font-semibold">复习建议</h2><ul class="mt-3 list-disc space-y-2 pl-5 text-sm text-slate-600"><li v-for="x in data.final_review?.study_plan" :key="x">{{x}}</li></ul></div></div><p class="text-xs text-slate-400">{{data.final_review?.disclaimer}}</p></div></main></template><script setup lang="ts">import {getInterview} from '~/utils/api';const route=useRoute(),data=ref<any>();onMounted(async()=>data.value=(await getInterview(String(route.params.id))).data)</script>
